import { createDbFromPool } from "@ogcio/db-core";
import type { Pool } from "pg";
import { describe, expect, it } from "vitest";
import type { DB } from "../../db/schema.js";
import {
  ScheduledEventModel,
  type ScheduleTaskInput,
} from "../../models/scheduled-event-model.js";

// Exercises the REAL multi-row `sql.join` insert generated by
// ScheduledEventModel through a mocked pg pool (no live DB). Kysely acquires a
// client via `pool.connect()` and runs `client.query(sql, params)`; we capture
// that call to assert the compiled statement and the per-row positional
// parameters.
type QueryCall = { text: string; params: unknown[] };

const normalizeSql = (sql: string): string => sql.replace(/\s+/g, " ").trim();

const buildPoolMock = (calls: QueryCall[]): Pool =>
  ({
    connect: () =>
      Promise.resolve({
        query: (text: string, params: unknown[]) => {
          calls.push({ text, params });
          return Promise.resolve({ rows: [], command: "INSERT", rowCount: 0 });
        },
        release: () => {},
      }),
  }) as unknown as Pool;

const task = (n: number): ScheduleTaskInput => ({
  webhookUrl: `https://hook/${n}`,
  webhookAuth: `auth-${n}`,
  executeAt: `2026-01-0${n}T00:00:00.000Z`,
});

describe("ScheduledEventModel.insertScheduledTasks", () => {
  it("builds a multi-row VALUES insert with one positional param per value", async () => {
    const calls: QueryCall[] = [];
    const model = new ScheduledEventModel(
      createDbFromPool<DB>(buildPoolMock(calls)),
    );

    await model.insertScheduledTasks([task(1), task(2)]);

    expect(calls).toHaveLength(1);
    expect(normalizeSql(calls[0].text)).toBe(
      "insert into scheduled_events( webhook_url, webhook_auth, execute_at ) values ($1, $2, $3), ($4, $5, $6)",
    );
    expect(calls[0].params).toEqual([
      "https://hook/1",
      "auth-1",
      "2026-01-01T00:00:00.000Z",
      "https://hook/2",
      "auth-2",
      "2026-01-02T00:00:00.000Z",
    ]);
  });

  it("builds a single-row insert for one task", async () => {
    const calls: QueryCall[] = [];
    const model = new ScheduledEventModel(
      createDbFromPool<DB>(buildPoolMock(calls)),
    );

    await model.insertScheduledTasks([task(1)]);

    expect(normalizeSql(calls[0].text)).toBe(
      "insert into scheduled_events( webhook_url, webhook_auth, execute_at ) values ($1, $2, $3)",
    );
    expect(calls[0].params).toEqual([
      "https://hook/1",
      "auth-1",
      "2026-01-01T00:00:00.000Z",
    ]);
  });
});
